  function timestamp(now){if(!Number.isSafeInteger(now)||now<0)throw Error('invalid-rule-suite-schedule-time');return now;}
  function deadlineFor(cp,id){let value=cp.deadlines.find(item=>item.id===id);
    if(!value){value={id,at:0,ready:false,starts:0,consumedStarts:-1,probeAt:0};cp.deadlines.push(value);}return value;}
  function configure(value,owner){const cp=checkpoint(value);if(typeof owner!=='string'||owner.length>160)throw Error('invalid-rule-suite-schedule-owner');
    return cp.owner===owner?cp:initial(owner);}
  function started(value,taskId,now){const cp=checkpoint(value);timestamp(now);
    for(const group of spec.groups){if(group.anchorTaskId!==taskId)continue;const deadline=deadlineFor(cp,group.id);
      deadline.starts++;deadline.at=group.availability?0:now+group.intervalMs;deadline.ready=false;deadline.probeAt=now+group.intervalMs;}
    return cp;
  }
  function isCheckpoint(taskId,beforeStep){return spec.checkpoints.some(point=>point.taskId===taskId&&point.beforeStep===beforeStep);}
  function availabilityFrame(roots,bundle,availability,projection){
    const result={ready:false,remainingMs:0,negativeConfirmed:false},readings=[],pattern=new RegExp(availability.countdownPattern);
    let count=0,complete=true,focusedOwners=0,foreignFocused=false,ownedWeb=false,focusedWebs=0,readableContent=false;
    const hasArea=bounds=>{const box=/^\[(-?\d+),(-?\d+)\]\[(-?\d+),(-?\d+)\]$/.exec(bounds??'');
      return!!box&&Number(box[3])>Number(box[1])&&Number(box[4])>Number(box[2]);};
    function walk(node,inApp,depth,inWeb=false){
      const a=node.attributes;if(++count>20000||depth>128){complete=false;return;}
      if(inApp&&a?.type==='Web'){ownedWeb=true;if(a.focused==='true'&&a.visible!=='false'&&hasArea(a.bounds))focusedWebs++;}
      if(a?.type==='Web'&&a.focused==='false')return;
