      if(a?.visible==='false'&&!(inWeb&&(a.type==='genericContainer'||a.type==='sectionWithoutName')&&zero))return;
      if(a?.type==='root'){inApp=a.bundleName===bundle;if(a.focused==='true'&&a.enabled!=='false'&&hasArea(a.bounds)){
        if(inApp)focusedOwners++;else foreignFocused=true;}}
      if(inApp){const text=a?.text??'';
        if(a?.type!=='root'&&hasArea(a?.bounds)&&(text.trim()||a?.description?.trim()))readableContent=true;
        if(!availability.readySiblingText&&text.trim()===availability.readyText)result.ready=true;
        const children=(node.children??[]).filter(child=>child.attributes?.visible!=='false');
        if(availability.readySiblingText&&children.some(child=>(child.attributes?.text??'').includes(availability.readySiblingText??''))&&
          children.some(child=>(child.attributes?.text??'').trim()===availability.readyText&&child.attributes?.enabled!=='false'))result.ready=true;
        if(children.some(child=>(child.attributes?.text??'').includes(availability.countdownSiblingText))){
