  function restrict(ids){if(!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.some(id=>!byId.has(id)))throw Error('invalid-native-task-allowlist');enabled=new Set(ids);}
  const box=value=>{const m=/^\[(-?\d+),(-?\d+)\]\[(-?\d+),(-?\d+)\]$/.exec(value||'');if(!m)return null;
    const[left,top,right,bottom]=m.slice(1).map(Number);return right>left&&bottom>top?{left,top,right,bottom}:null;};
  function snapshotBounds(value){return box(value);}
function repeatStopVisible(trees, title, state, activeLabels = []) {
    if (!trees || !title || !state) {
        return false;
    }
    let inspected = 0;
    const label = (node) => (node.attributes?.text || node.attributes?.description || '').trim();
    const sameRow = (a, b) => {
        const ah = a.bottom - a.top, bh = b.bottom - b.top;
        const gap = Math.max(0, Math.max(a.top, b.top) - Math.min(a.bottom, b.bottom));
        return gap <= Math.min(ah, bh) * 0.35 &&
            Math.abs(a.top + ah / 2 - b.top - bh / 2) <= Math.max(ah, bh) * 0.8;
    };
