    if (!trees || present.length === 0 || absent.length === 0) {
        return false;
    }
    const labels = [];
    let inspected = 0;
    const visit = (node, depth, inWeb = false) => {
        if (!node || depth > 128 || ++inspected > 20000 || node.attributes?.enabled === 'false') {
            return;
        }
        const a = node.attributes;
        if (a?.type === 'root' && a.focused === 'false') {
            return;
        }
