  function initial(now,sequence=0){return{schema:1,actionSequence:sequence,taskId:'',step:0,mode:'candidate',nextAt:now,
    startedAt:now,suiteUntil:now+20000,sequenceUntil:0,repeatReadyAt:0,repeatUntil:0,lastProgressAt:now,cycles:0,tried:[],skipCount:0,lastFrame:'',
    verify:null,landing:null,landingDormant:null,landingDone:false,resume:null,scheduledIds:[],search:0,done:false,note:'准备原任务流程',
