}

const __quietstartConfiguredControls={"tasks":[{"id":"quietstart.qidian-welfare-reward","key":"task.quietstart.qidian-welfare-reward"},{"id":"quietstart.qidian-welfare-hourly","key":"task.quietstart.qidian-welfare-hourly"},{"id":"quietstart.qidian-welfare-three-ads","key":"task.quietstart.qidian-welfare-three-ads"},{"id":"quietstart.qidian-welfare-one-ad","key":"task.quietstart.qidian-welfare-one-ad"},{"id":"quietstart.qidian-welfare-astronaut","key":"task.quietstart.qidian-welfare-astronaut"},{"id":"quietstart.qidian-welfare-scroll","key":"task.quietstart.qidian-welfare-scroll"},{"id":"quietstart.qidian-welfare-popup","key":"task.quietstart.qidian-welfare-popup"},{"id":"quietstart.qidian-welfare-scroll-more","key":"task.quietstart.qidian-welfare-scroll-more"}],"stages":[],"safeFinish":true,"supportTasks":["quietstart.qidian-welfare-scroll","quietstart.qidian-welfare-popup","quietstart.qidian-welfare-scroll-more"]};
// Author-side settings adapter. This never changes target declarations, input
// permissions, original checkpoints, or an application's completion conditions.
export async function onEvent(ctx, event) {
  if (event?.kind === 'input-select') {
    if (event.input.kind === 'welfare-popup') return selectWelfareClose(event.input.before, event.observation, welfarePopup(event.observation.queries.owner));
    if (event.input.kind === 'welfare-or-chooser') return chooseWelfareOrChooser(event);
    return chooseVisitInput(event);
  }
  const config = await ctx.config.read();
  const controls = typeof __quietstartConfiguredControls === 'object' ? __quietstartConfiguredControls : {};
  if (controls.tasks?.length) {
    const disabled = new Set(controls.tasks.filter(task => config[task.key] === false).map(task => task.id));
    // Local settings only subtract from the host's current authorized list.
    // Missing native lists retain the original adapter's fail-closed behavior.
    if (Array.isArray(event?.enabledTaskIds)) {
      const selected = event.enabledTaskIds.filter(id => !disabled.has(id));
      if (controls.supportTasks?.length && controls.tasks.filter(task => !controls.supportTasks.includes(task.id)).every(task => disabled.has(task.id))) selected.splice(0);
      event = controls.safeFinish ? { ...event, selectedTaskIds: selected } : { ...event, enabledTaskIds: selected };
    }
    else if (disabled.size === controls.tasks.length) event = { ...event, enabledTaskIds: [] };
  }
  const prefix = typeof config.progressPrefix === 'string' ? config.progressPrefix.trim() : '';
  const message = text => prefix && typeof text === 'string' && text ? (prefix + ' · ' + text).slice(0, 500) : text;
  const port = { ...ctx, config: { ...ctx.config, read: async () => config },
    ...(prefix && ctx.ui?.publish ? { ui: { ...ctx.ui,
      publish: item => ctx.ui.publish({ ...item, message: message(item.message) }) } } : {}) };
  const result = await __quietstartConfiguredOriginalEvent(port, event);
  if (prefix && typeof result?.message === 'string') result.message = message(result.message);
  const delay = config.nextActionDelayMs;
  if (result?.status === 'waiting' && result.next && Number.isSafeInteger(delay) && delay > 0) {
    result.next = { ...result.next, at: Math.max(result.next.at, (await ctx.clock.now()) + delay) };
  }
  return result;
}

function decideQidianSweep(cp, frame, enabled, now) {
      cp.sweep ||= sweep.initial();
      return sweep.decide(cp.sweep,frame,{bundle:__quietstartQidianPlan.originalRules.appliesTo[0],entryActive:true,sequenceActive:cp.sequenceUntil>0&&cp.step>0,
        repeatPackId:cp.repeatUntil>0?cp.taskId:'',repeatReadyAt:cp.repeatReadyAt||0,repeatIdleMs:__quietstartQidianPlan.originalRules.tasks.find(t=>t.id===cp.taskId)?.repeat?.idleMs||0,
        enabledTaskIds:enabled,triedIds:cp.tried,actionSequence:cp.actionSequence},now);
