async function chooseVisitInput(event) {
  const { before, now, enabled, allowedTasks } = event.input;
  const observation = event.observation;
  const frame = observation.queries?.owner;
  if (!frame) throw Error('coherent-owner-query-missing');
  flow.restrict(allowedTasks);
  const popup = welfarePopup(frame);
  if (popup.present) return selectWelfareClose(before, observation, popup);
  if (frame.ownerValid === true && frame.complete === true) delete before.welfarePopupDismissed;
  const step = flow.decideReady(before, frame, event.at);
  const command = step.command;
  const binding = __quietstartQidianTaskBindings[command?.taskId];
  const button = binding && __quietstartQidianBindings[binding.key].buttonQuery;
  const visitStart = await chooseNativeVisitStart(step, observation, now, before.actionSequence, binding, observation.queries?.[button]);
  if (visitStart) {
    return { action: { kind: 'tap', targetRef: visitStart.decision.intent.targetRef },
      value: { before, step, visitStart } };
  }
  let action = null;
  const search = command?.kind === 'search' ? decideQidianSweep(step.checkpoint, frame, enabled, event.at) : undefined;
  if (search?.intent?.kind === 'relative-swipe' && search.intent.sequence === before.actionSequence) {
    const { sequence, ...swipe } = search.intent;
    action = swipe;
  }
  if (command?.kind === 'tap' && command.sequence === before.actionSequence) {
    action = { kind: 'tap', targetRef: command.targetRef };
  }
  return { action, value: { before, step, search, hasInput: !!action, ...(action ? {} : { observation }) } };
}

async function chooseNativeVisitStart(step, observation, now, sequence, binding, target) {
  const command = step.command, checkpoint = step.checkpoint;
  if (command?.kind !== 'landing' || checkpoint.landing || checkpoint.landingDormant ||
      checkpoint.actionSequence !== sequence || observation.ownerValid !== true ||
      observation.queries?.owner?.complete !== true || !binding || target?.complete !== true ||
      target.ownerValid !== true || target.matched !== true || !target.targetRef) return;

  const landing = suite.initial(command.taskId, now, sequence);
  const needsHost = {};
  const pure = { clock: { now: () => now }, rules: { resolve(id, ticket) {
    if (id === binding.visitQuery && ticket === undefined) return { matched: false };
    throw needsHost;
  } } };
  let facts;
  try { facts = await nativeFacts(pure, landing, binding, () => clone(observation)); }
  catch (error) { if (error === needsHost) return; throw error; }
  const decision = suite.decide(landing, facts);
  const intent = decision.intent;
  if (decision.applied?.effect !== 'source-tapped' || intent?.kind !== 'tap' ||
      intent.targetRef !== target.targetRef || intent.sequence !== sequence || intent.evidenceRefs?.length) return;

  return { decision, observation: { nativeFacts: facts.nativeFacts } };
}

async function publishWelfarePopup(ctx, before, now, selection) {
  const result = await dismissWelfarePopup(ctx, before, undefined, now, selection);
  await ctx.ui.publish({ kind: 'capsule', message: result.message, stopped: false });
  return result;
}

async function chooseWelfareOrChooser(event) {
  const { before, landing, visit, allowNewVisits } = event.input;
  const observation = event.observation, frame = observation.queries.owner;
  const popup = welfarePopup(frame);
  if (popup.present) return selectWelfareClose(before, observation, popup);

  const noInput = { action: null, value: { observation } };
  const binding = __quietstartQidianTaskBindings[landing.taskId];
  const config = __quietstartQidianBindings[binding.key];
  const chooser = observation.visitQueries[config.chooserQuery];
  if (!chooser?.optionRef || !observation.selectableVisitRefs?.includes(chooser.optionRef)) return noInput;
  const needsHost = {};
  const pure = { clock: { now: () => event.at }, rules: { resolve(id, ticket) {
    if (ticket === landing.visitTicket && id === config.visitQuery) return clone(visit);
    throw needsHost;
  } } };
  let facts;
  try { facts = await nativeFacts(pure, landing, binding, () => clone(observation)); }
  catch (error) { if (error === needsHost) return noInput; throw error; }
  facts.nativeFacts.allowNewVisits = allowNewVisits;
  const decision = suite.decide(landing, facts), intent = decision.intent;
  if (decision.applied?.effect !== 'chooser-selected' || intent?.kind !== 'tap' ||
      intent.sequence !== before.actionSequence || intent.targetRef !== chooser.optionRef) return noInput;
  return { action: { kind: 'tap', targetRef: intent.targetRef },
    value: { visitChoice: { decision, observation: { nativeFacts: facts.nativeFacts } },
      clearPopupDismissal: frame.ownerValid === true && frame.complete === true } };
}

function visitProgress(policy) {
  let visit = policy.landing?.visit;
  while (visit?.phase === 'child') visit = visit.child;
  const step = visit ?? policy.giftInstall ?? policy.child?.checkpoint ?? policy;
  if (['landing-dwell', 'page-dwell', 'dwell'].includes(step.phase)) {
    if (step.note === '等待系统遮挡消失') return { message: step.note };
    // While watching for a late chooser, nextReadAt is a probe, not the end of the dwell.
    const dwellUntil = Number.isSafeInteger(step.chooserDwellUntil) && step.chooserDwellUntil > 0
      ? step.chooserDwellUntil : step.nextReadAt ?? policy.nextAt;
    return { message: '正在停留', countdownUntil: dwellUntil };
  }
  if (step.phase === 'transition' || step.phase === 'chooser' || policy.giftInstall?.phase === 'opening') {
    const selecting = !step.chooserSelections && (step.chooserSeen || step.chooserWaits > 0);
    return { message: selecting ? '正在选择应用' : '正在打开应用' };
  }
  return undefined;
}
function visitCapsule(result) {
  const stopped = result.status === 'complete';
  const progress = stopped ? undefined : visitProgress(result.checkpoint.policy);
  return { kind: 'capsule', message: result.message, stopped, ...progress };
}

function hasVisibleSourceTask(landing, facts, frame, labels, config, tasks, flow) {
  if (landing.visitTicket || landing.visit.phase !== 'entry' || facts.foreground?.owner !== true ||
      frame?.complete !== true || frame.ownerValid !== true || facts.queries?.earned?.matched ||
      facts.queries?.['declared-container']?.matched || labels?.ownerValid !== true || !Array.isArray(labels.texts)) return false;
  const hints = [config.spec.promptText, ...(config.spec.promptKeywords || [])].filter(Boolean);
  const compact = value => value.replace(/\s/g, '');
  if (labels.texts.some(label => hints.some(hint => compact(label).includes(compact(hint))))) return false;
  const task = tasks.find(item => item.id === landing.taskId);
  return !!task && flow.candidates(frame, task, 0).length === 1;
