    !!frame.frameRef && frame.frameRef === cachedFrame?.frameRef;
}

function completedExternalDwell(visit, foreground, owner, now, dwellMs) {
  const arrivedAt = visit.chooserArrivedAt ?? visit.landingConfirmedAt;
